public class Main {
    public static void main(String[] args) {
        Car car1 = new Car("Honda", "Civic", "VIN123");
        Car car2 = new Car("Honda", "Civic", "VIN123"); // same data, different object
        Car car3 = car1; // reference copy, NOT a new object

        System.out.println(car1 == car2);      // false: two distinct objects in memory
        System.out.println(car1 == car3);      // true: car3 points to the SAME object as car1
        System.out.println(car1.equals(car2)); // true: same vinNumber, logically equal
    }
}

// The Car class, this time with identity-aware equals/hashCode
class Car {
    private String brand;
    private String model;
    private String vinNumber; // unique per real physical car

    public Car(String brand, String model, String vinNumber) {
        this.brand = brand;
        this.model = model;
        this.vinNumber = vinNumber;
    }

    // Overridden to compare OBJECTS BY DATA (same vinNumber) instead of by identity
    @Override
    public boolean equals(Object other) {
        if (this == other) return true; // same object, quick exit
        if (!(other instanceof Car)) return false;
        Car otherCar = (Car) other;
        return vinNumber.equals(otherCar.vinNumber);
    }

    // Must be overridden alongside equals(), so hash-based collections stay consistent
    @Override
    public int hashCode() {
        return vinNumber.hashCode();
    }
}

