# The Car class, this time with identity-aware equality
class Car:
    def __init__(self, brand, model, vin_number):
        self.brand = brand
        self.model = model
        self.vin_number = vin_number  # unique per real physical car

    # Overridden to compare OBJECTS BY DATA (same vin_number) instead of by identity
    def __eq__(self, other):
        if not isinstance(other, Car):
            return False
        return self.vin_number == other.vin_number

    # Must be overridden alongside __eq__, so hash-based collections stay consistent
    def __hash__(self):
        return hash(self.vin_number)


if __name__ == "__main__":
    car1 = Car("Honda", "Civic", "VIN123")
    car2 = Car("Honda", "Civic", "VIN123")  # same data, different object
    car3 = car1  # reference copy, NOT a new object

    print(car1 is car2)   # False: two distinct objects
    print(car1 is car3)   # True: car3 references the SAME object as car1
    print(car1 == car2)   # True: same vin_number, logically equal via __eq__

