#include <iostream>
#include <string>
using namespace std;

// The Car class, this time with an identity-aware equals() method
class Car {
private:
    string brand;
    string model;
    string vinNumber; // unique per real physical car

public:
    Car(string brand, string model, string vinNumber) {
        this->brand = brand;
        this->model = model;
        this->vinNumber = vinNumber;
    }

    // Compares OBJECTS BY DATA (same vinNumber) instead of by pointer identity
    bool equals(Car* other) {
        if (other == nullptr) return false;
        return vinNumber == other->vinNumber;
    }
};

int main() {
    Car* car1 = new Car("Honda", "Civic", "VIN123");
    Car* car2 = new Car("Honda", "Civic", "VIN123"); // same data, different object
    Car* car3 = car1; // pointer copy, NOT a new object

    cout << (car1 == car2) << endl;        // 0 (false): two distinct objects
    cout << (car1 == car3) << endl;        // 1 (true): car3 points to the SAME object as car1
    cout << car1->equals(car2) << endl;    // 1 (true): same vinNumber, logically equal

    delete car1;
    delete car2;
    return 0;
}
